-- OWNED_BY: generic. Reviewable source decisions and actual discharge/billing/readiness projections.
BEGIN;
CREATE FUNCTION rs_signed_discharge_board(p_stay_id bigint DEFAULT NULL,p_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE t uuid:=current_tenant_id();ids bigint[];result_value jsonb;
BEGIN
 PERFORM ops_actor(ARRAY['super_admin','head_operation','direktur','admin','admin_faskes','dokter','doctor','nurse','perawat','pharmacist','apoteker']);
 IF p_offset IS NULL OR p_offset<0 OR p_offset>100000 THEN RAISE EXCEPTION 'Offset tidak valid';END IF;
 IF p_stay_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM inpatient_stays WHERE id=p_stay_id AND tenant_id=t) THEN RAISE EXCEPTION 'Stay bukan milik tenant';END IF;
 SELECT array_agg(id) INTO ids FROM (SELECT id FROM inpatient_stays WHERE tenant_id=t AND (p_stay_id IS NULL OR id=p_stay_id) ORDER BY id DESC LIMIT 51 OFFSET p_offset) source;
 SELECT jsonb_build_object('tenant_id',t,'offset',p_offset,
 'stays',coalesce((SELECT jsonb_agg(to_jsonb(s)||jsonb_build_object('source_stay_snapshot',to_jsonb(s),'episode',(SELECT to_jsonb(e) FROM rs_care_episodes e WHERE admission_id=s.admission_id AND tenant_id=t AND state='active'),'billing_setup',(SELECT to_jsonb(b) FROM rs_billing_setups b WHERE stay_id=s.id AND tenant_id=t AND state='active'),'checklists',(SELECT coalesce(jsonb_agg(to_jsonb(o)),'[]') FROM rs_work_orders o WHERE admission_id=s.admission_id AND tenant_id=t AND kind='rs-discharge'),'pharmacy_remaining',(SELECT coalesce(sum(d.qty-rs_medication_custody_used(d.id)),0) FROM pharmacy_dispense_items d JOIN prescription_items i ON i.id=d.rx_item_id JOIN rs_prescription_contexts c ON c.rx_id=i.rx_id WHERE c.admission_id=s.admission_id AND c.tenant_id=t),'pending_prescriptions',(SELECT count(*) FROM prescriptions p JOIN rs_prescription_contexts c ON c.rx_id=p.id WHERE c.admission_id=s.admission_id AND c.tenant_id=t AND p.status='Baru'),'active_medication_plans',(SELECT count(*) FROM rs_mar_plans p JOIN mar_jadwal j ON j.id=p.schedule_id WHERE j.admission_id=s.admission_id AND p.tenant_id=t AND p.state IN ('draft','verified')),'custody_drafts',(SELECT count(*) FROM rs_medication_custody_events e JOIN pharmacy_dispense_items d ON d.id=e.dispense_item_id JOIN prescription_items i ON i.id=d.rx_item_id JOIN rs_prescription_contexts c ON c.rx_id=i.rx_id WHERE e.tenant_id=t AND c.admission_id=s.admission_id AND c.tenant_id=t AND e.state IN ('draft','posting')))) FROM inpatient_stays s WHERE id=ANY(ids) AND tenant_id=t),'[]'),
 'templates',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM ops_policy_versions p WHERE tenant_id=t AND scope='rs-discharge' AND kind='clinical_template' AND state='active' AND effective_at<=now() AND payload->>'purpose'='inpatient_discharge'),'[]'),
 'records',coalesce((SELECT jsonb_agg(to_jsonb(r)) FROM (SELECT record.* FROM rs_clinical_records record JOIN ops_policy_versions p ON p.id=record.policy_id JOIN inpatient_stays s ON s.admission_id=record.admission_id WHERE record.tenant_id=t AND p.tenant_id=t AND p.scope='rs-discharge' AND p.payload->>'purpose'='inpatient_discharge' AND rs_clinical_can_read(p.id) AND s.id=ANY(ids) ORDER BY record.id DESC LIMIT 201 OFFSET p_offset) r),'[]'),
 'executions',coalesce((SELECT jsonb_agg(to_jsonb(e)||jsonb_build_object('source_resume',to_jsonb(d))) FROM rs_discharge_executions e JOIN inpatient_discharges d ON d.id=e.source_discharge_id WHERE e.tenant_id=t AND e.stay_id=ANY(ids) AND EXISTS(SELECT 1 FROM rs_clinical_records c WHERE c.id=e.clinical_record_id AND c.tenant_id=t AND rs_clinical_can_read(c.policy_id))),'[]'),
 'invoices',coalesce((SELECT jsonb_agg(to_jsonb(i)) FROM rs_final_invoices i JOIN rs_billing_setups b ON b.id=i.setup_id WHERE i.tenant_id=t AND b.tenant_id=t AND b.stay_id=ANY(ids)),'[]')
 ) INTO result_value;RETURN result_value;
END $$;
REVOKE ALL ON FUNCTION rs_signed_discharge_board(bigint,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION rs_signed_discharge_board(bigint,integer) TO authenticated;
COMMIT;
